CREATE TABLE business_audit (id VARCHAR2(36) PRIMARY KEY, actor VARCHAR2(128) NOT NULL, action VARCHAR2(80) NOT NULL, entity_id VARCHAR2(128) NOT NULL, trace_id VARCHAR2(64), fields CLOB, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
CREATE OR REPLACE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON business_audit BEGIN RAISE_APPLICATION_ERROR(-20001, 'Audit is append only'); END;
/
CREATE TABLE event_outbox (id VARCHAR2(36) PRIMARY KEY, event_type VARCHAR2(100) NOT NULL, payload CLOB NOT NULL, trace_id VARCHAR2(64), created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, published_at TIMESTAMP WITH TIME ZONE, attempts NUMBER(3) DEFAULT 0 NOT NULL, next_attempt TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, dead NUMBER(1) DEFAULT 0 NOT NULL);
CREATE INDEX outbox_due ON event_outbox(dead, published_at, next_attempt);
CREATE TABLE event_inbox (id VARCHAR2(36) PRIMARY KEY, received_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE idempotency_record (actor VARCHAR2(128), request_key VARCHAR2(128), operation VARCHAR2(80), request_hash VARCHAR2(64) NOT NULL, response CLOB NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, PRIMARY KEY(actor, request_key, operation));
